function chirpPath() {
	const pts = [];
	const W = 760, H = 220, n = 3;
	for (let c = 0; c < n; c++) {
		const x0 = c * W / n;
		pts.push(`M ${x0} ${H}`);
		pts.push(`L ${x0 + W / n - 8} 20`);
	}
	return pts.join(" ");
}
function chirpWave() {
	let p = "M 0 60";
	for (let x = 0; x <= 760; x += 2) {
		const t = x % 253 / 253;
		const phase = 2 * Math.PI * (2 * t + 9 * t * t);
		p += ` L ${x} ${60 - 45 * Math.sin(phase)}`;
	}
	return p;
}
